package lk.sliit.nutricare.message;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="secure_messages")public class SecureMessage{@Id private UUID id;@Column(nullable=false)private UUID senderId;@Column(nullable=false)private UUID recipientId;@Column(nullable=false)private UUID patientId;@Column(nullable=false,length=2000)private String body;@Column(nullable=false)private Instant sentAt;protected SecureMessage(){}public SecureMessage(UUID s,UUID r,UUID p,String body){id=UUID.randomUUID();senderId=s;recipientId=r;patientId=p;this.body=body;sentAt=Instant.now();}public UUID getId(){return id;}public UUID getSenderId(){return senderId;}public UUID getRecipientId(){return recipientId;}public UUID getPatientId(){return patientId;}public String getBody(){return body;}public Instant getSentAt(){return sentAt;}}
